m:addOverride('xi.player.onGameIn', function(player, firstLogin, zoning)
    super(player, firstLogin, zoning)

    -- Only once, on an actual login (not a zone change).
    if done or zoning then
        return
    end
    done = true

    -- NOTE on SpawnMob (luautils.cpp): passing a respawntime (arg3) ONLY sets m_RespawnTime +
    -- m_AllowRespawn and does NOT spawn the mob -- the actual Spawn() happens only when arg3 is
    -- omitted. So we must make TWO calls per NM: one to force it up now, one to configure its
    -- 5-minute respawn for after it is killed (incl. lottery/placeholder NMs, whose own
    -- onMobDeath does not self-respawn -- setting m_AllowRespawn here makes them re-pop anyway).
    for i = 1, #NM_IDS do
        pcall(SpawnMob, NM_IDS[i])          -- Spawn() it now (arg3 omitted -> else branch)
        pcall(SpawnMob, NM_IDS[i], nil, RESPAWN) -- set m_RespawnTime + m_AllowRespawn for post-death
    end
end)

return m
